"use client";
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useParams, useRouter } from 'next/navigation';
import Sidebar from "../../../components/sidebar";
import Navbar from "../../../components/Navbar";

export default function Edituser() {
  const [etudiant, setEtudiant] = useState(null);
  const [groupes, setGroupes] = useState([]);
  const [idGroupe, setIdGroupe] = useState("");
  const { id } = useParams();
  const router = useRouter();

  useEffect(() => {
    if (id) {
      fetchEtudiant();
      fetchGroupes();
    }
  }, [id]);

  const fetchEtudiant = async () => {
    try {
      const response = await axios.get(`http://localhost:5000/api/getetudiant/${id}`);
      setEtudiant(response.data);
      setIdGroupe(response.data.idGroupe || "");
    } catch (err) {
      console.error("Erreur récupération étudiant:", err);
      alert("Erreur lors du chargement des données");
    }
  };

  const fetchGroupes = async () => {
    try {
      const response = await axios.get("http://localhost:5000/api/groupes");
      setGroupes(response.data);
    } catch (err) {
      console.error("Erreur récupération groupes:", err);
    }
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    try {
      await axios.put(`http://localhost:5000/api/modifierGroupe/${etudiant.idEtudiant}`, {
        idGroupe: idGroupe
      });
      router.push('/geneman');
    } catch (err) {
      console.error("Erreur modification:", err);
      alert("Erreur lors de la modification");
    }
  };

  if (!etudiant) {
    return (
      <div className="flex items-center justify-center h-screen">
        <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-blue-500"></div>
      </div>
    );
  }

  return (
    <div className="flex h-screen w-screen bg-gray-100">
      <Sidebar />
      
      <div className="flex flex-col w-full">
        <Navbar />

        <div className="flex flex-1 justify-center items-center p-4">
          <div className="bg-white p-8 rounded-2xl shadow-lg w-full max-w-lg">
            <h1 className="text-2xl font-bold text-gray-800 text-center mb-6">
              Modifier le groupe de {etudiant.nom} {etudiant.prenom}
            </h1>

            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Nom</label>
                  <input
                    type="text"
                    value={etudiant.nom}
                    className="w-full px-3 py-2 border rounded-md bg-gray-100"
                    readOnly
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Prénom</label>
                  <input
                    type="text"
                    value={etudiant.prenom}
                    className="w-full px-3 py-2 border rounded-md bg-gray-100"
                    readOnly
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Groupe</label>
                <select
                  value={idGroupe}
                  onChange={(e) => setIdGroupe(e.target.value)}
                  className="w-full px-3 py-2 border rounded-md"
                >
                  <option value="">Sélectionner un groupe</option>
                  {groupes.map((groupe) => (
                    <option key={groupe.idGroupe} value={groupe.idGroupe}>
                      {groupe.nomGroupe}
                    </option>
                  ))}
                </select>
              </div>

              <button
                type="submit"
                className="w-full bg-blue-600 text-white py-2 px-4 rounded-md hover:bg-blue-700 transition-colors mt-4"
              >
                Enregistrer les modifications
              </button>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
}